declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject;

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateAssetTenantVO
{
    public static function empty(): TemplateAssetTenantVO
    {
        return new TemplateAssetTenantVO(null);
    }
    public static function from(TemplateAssetTenantVO|TenantRef|null $value): TemplateAssetTenantVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateAssetTenantVO
    {
        if ($value instanceof TemplateAssetTenantVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new TemplateAssetTenantVO($value);
        } elseif (is_a($value, TenantRef::class)) {
            return new TemplateAssetTenantVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['tenant'], [$value], ['TenantRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): TemplateAssetTenantVO
    {
        if ($value instanceof TemplateAssetTenantVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TemplateAssetTenantVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?TenantRef $tenant
    ) {
    }
    public function value(): ?TenantRef
    {
        return $this->tenant;
    }
    public function equals(?TemplateAssetTenantVO $other): bool
    {
        return $this->value()?->uid() == $other?->value()?->uid();
    }
}
